using UnityEngine;
using System.Collections;

public class SwapBehavior : MonoBehaviour
{
    public GameObject target;
    
    public void ExecuteSwap(GameObject from)
    {
        if (target != null)
        {
            Vector2Int originalPosition = new Vector2Int(Mathf.RoundToInt(from.transform.position.x), Mathf.RoundToInt(from.transform.position.z));
            Vector2Int targetPosition = new Vector2Int(Mathf.RoundToInt(target.transform.position.x), Mathf.RoundToInt(target.transform.position.z));
            from.transform.position = targetPosition;
            target.transform.position = originalPosition;
        }
    }
}
